#include <vector>
#include <numeric>
#include <algorithm>

class Solution {
public:
    int maxScoreWithCoPrimeElement(std::vector<int>& nums, int k) {
        std::vector<int> valid;
        for (int x : nums) {
            if (std::gcd(x, k) == 1) {
                valid.push_back(x);
            }
        }
        if (valid.empty()) return 0;
        int posSum = 0;
        int maxVal = valid[0];
        for (int x : valid) {
            if (x > 0) posSum += x;
            maxVal = std::max(maxVal, x);
        }
        return posSum > 0 ? posSum : maxVal;
    }
};

import java.util.*;

class Solution {
    private int gcd(int a, int b) {
        while (b != 0) {
            int t = b;
            b = a % b;
            a = t;
        }
        return a;
    }

    public int maxScoreWithCoPrimeElement(int[] nums, int k) {
        List<Integer> valid = new ArrayList<>();
        for (int x : nums) {
            if (gcd(Math.abs(x), Math.abs(k)) == 1) {
                valid.add(x);
            }
        }
        if (valid.isEmpty()) return 0;
        int posSum = 0;
        int maxVal = valid.get(0);
        for (int x : valid) {
            if (x > 0) posSum += x;
            maxVal = Math.max(maxVal, x);
        }
        return posSum > 0 ? posSum : maxVal;
    }
}

function gcd(a, b) {
    while (b !== 0) {
        let t = b;
        b = a % b;
        a = t;
    }
    return a;
}

function maxScoreWithCoPrimeElement(nums, k) {
    const valid = nums.filter(x => gcd(Math.abs(x), Math.abs(k)) === 1);
    if (valid.length === 0) return 0;
    const posSum = valid.filter(x => x > 0).reduce((acc, v) => acc + v, 0);
    return posSum > 0 ? posSum : Math.max(...valid);
}
